//! Muted native decoder/mixer acceptance probe; never changes the user's database.
use anyhow::{ensure,Result};
use musicos_desktop::{local::{LocalPlaybackService,LocalPlaybackCommand,listening::Listening},models::PlaybackPreferences};
use std::time::{Duration,Instant};
fn wait(mut f:impl FnMut()->bool)->Result<()>{let end=Instant::now()+Duration::from_secs(10);while !f(){ensure!(Instant::now()<end,"Playback acknowledgement timed out");std::thread::sleep(Duration::from_millis(10));}Ok(())}
fn main()->Result<()>{let args=std::env::args().collect::<Vec<_>>();let conn=rusqlite::Connection::open_with_flags(&args[1],rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)?;let (path,title,artist,album,duration):(String,String,String,String,i32)=conn.query_row("SELECT path,title,artist,album,duration FROM tracks WHERE duration>60 AND deleted_at IS NULL LIMIT 1",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?)))?;
 let temp=tempfile::tempdir()?;let db_path=temp.path().join("test.sqlite");let db=musicos_init::database::Db::open(db_path.to_str().unwrap())?;let id=db.insert_track(&path,&title,&artist,&album,duration,std::fs::metadata(&path)?.len() as i64,1)?;drop(db);
 let service=LocalPlaybackService::start_with_preferences(db_path,PlaybackPreferences{volume:0.,..Default::default()})?;service.send(LocalPlaybackCommand::PlayTracks{ids:vec![id,id],start_index:0})?;wait(||service.snapshot().position>0.2)?;
 let settings=Listening{reverb:0.25,speed:1.5,gains3:[3.,-2.,1.],..Default::default()}.normalize();let change_started=Instant::now();service.send(LocalPlaybackCommand::SetListening(settings.clone()))?;wait(||{let s=service.snapshot();s.listening==settings&&s.listening_applied})?;
 let response_ms=change_started.elapsed().as_secs_f64()*1000.;ensure!(response_ms<750.,"Control response took {response_ms} ms");
 let ready_position=service.snapshot().position;wait(||service.snapshot().position>ready_position+0.3)?;let start=service.snapshot().position;let timer=Instant::now();std::thread::sleep(Duration::from_millis(2000));let rate=(service.snapshot().position-start)/timer.elapsed().as_secs_f32();ensure!((rate-1.5).abs()<0.12,"Audible source rate was {rate}");
 let mut rapid_response_ms=Vec::new();for speed in [0.5,1.25,2.,0.75,1.] {let changed=Listening{speed,..settings.clone()}.normalize();let before=service.snapshot().position;let timer=Instant::now();service.send(LocalPlaybackCommand::SetListening(changed.clone()))?;wait(||{let s=service.snapshot();s.listening==changed&&s.listening_applied})?;rapid_response_ms.push(timer.elapsed().as_secs_f64()*1000.);ensure!(service.snapshot().position>=before,"Parameter change rewound source position");ensure!(rapid_response_ms.last().unwrap()<&750.,"Rapid control response timed out");}
 service.send(LocalPlaybackCommand::Pause)?;wait(||!service.snapshot().is_playing)?;let paused=service.snapshot().position;std::thread::sleep(Duration::from_millis(200));ensure!((service.snapshot().position-paused).abs()<0.01,"Pause moved source clock");
 let independent=Listening{linked:false,speed:0.75,pitch:5.,bands:8,gains8:[1.;8],..settings};service.send(LocalPlaybackCommand::SetListening(independent.clone()))?;wait(||{let s=service.snapshot();s.listening==independent&&s.listening_applied})?;ensure!(!service.snapshot().is_playing,"Changing controls resumed paused music");service.send(LocalPlaybackCommand::SeekAbsolute(12.))?;wait(||(service.snapshot().position-12.).abs()<0.1)?;
 let report=serde_json::json!({"native_decoder_and_output":true,"control_response_ms":response_ms,"rapid_response_ms":rapid_response_ms,"reverb_applied":true,"test_volume":0,"linked_pitch":12_f32*1.5_f32.log2(),"measured_source_rate":rate,"eq_three_and_eight":true,"acknowledged_controls":true,"independent_pitch_speed":true,"pause_frozen":true,"seek_source_time":true,"listening_acceptance":false});println!("{}",report);if let Some(output)=args.get(2){std::fs::write(output,serde_json::to_vec_pretty(&report)?)?;}Ok(())}
